/** Readings the annotated font shows only with a variation selector (數一數, 箱子, 曲線, 蘿蔔). */
const alternateReadings: Record<string, string> = {
  數ㄕㄨˇ: "\u{E01E1}",
  "子˙ㄗ": "\u{E01E1}",
  曲ㄑㄩ: "\u{E01E1}",
  "蔔˙ㄅㄛ": "\u{E01E1}",
};

export const isHan = (character: string) => /\p{Script=Han}/u.test(character);

/** The selectors that make each character of an instruction show its reading. */
export function mathPromptVariants(id: string): Record<number, string> {
  const readings = mathPromptReadings[id]?.split(" ") ?? [];
  const variants: Record<number, string> = {};
  let syllable = 0;
  Array.from(mathPrompts[id] ?? "").forEach((character, index) => {
    if (!isHan(character)) return;
    const selector = alternateReadings[character + readings[syllable++]];
    if (selector) variants[index] = selector;
  });
  return variants;
}

export const mathPromptId = (question: { kind: string; target: number }) =>
  question.kind === "count" ? "count" : `draw-${question.target}`;

/** Clips re-recorded after their sentence changed; the query skips a cached old clip. */
const promptVersions: Record<string, number> = { count: 2 };

/** Page-relative, like every public file (see CLAUDE.md). */
export const mathPromptUrl = (id: string) => `math-audio/${id}.m4a?v=${promptVersions[id] ?? 1}`;
